import React, { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Trash2, Search, Download, ChevronDown, ChevronUp, RotateCcw, Pencil } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';
import { useApp } from '../context/AppContext';
import { exportToCSV } from '../utils/csv';
import Modal from './Modal';

export default function HistoryPanel() {
  const { dailyLogs, activities, todayKey, goal, actions } = useApp();
  const [searchQuery, setSearchQuery] = useState('');
  const [expandedDays, setExpandedDays] = useState({ [todayKey]: true });
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [confirmReset, setConfirmReset] = useState(false);
  const [editingEntry, setEditingEntry] = useState(null);
  const [editReps, setEditReps] = useState('');
  const [editNotes, setEditNotes] = useState('');
  const [editActivityId, setEditActivityId] = useState(null);

  // Build sorted day list with totals
  const days = useMemo(() => {
    return Object.entries(dailyLogs)
      .map(([date, entries]) => ({
        date,
        entries,
        total: entries.reduce((sum, e) => sum + e.totalTouches, 0),
        sessionCount: entries.length,
      }))
      .filter(day => day.entries.length > 0)
      .sort((a, b) => b.date.localeCompare(a.date));
  }, [dailyLogs]);

  const chartData = useMemo(() => {
    return days
      .slice()
      .reverse()
      .map(day => ({
        date: day.date,
        label: new Date(day.date + 'T12:00:00').toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        touches: day.total,
      }));
  }, [days]);

  // Filter by search
  const filteredDays = useMemo(() => {
    if (!searchQuery.trim()) return days;
    const q = searchQuery.toLowerCase();
    return days
      .map(day => ({
        ...day,
        entries: day.entries.filter(e =>
          e.activityName.toLowerCase().includes(q) ||
          (e.notes && e.notes.toLowerCase().includes(q))
        ),
      }))
      .filter(day => day.entries.length > 0);
  }, [days, searchQuery]);

  const toggleDay = (date) => {
    setExpandedDays(prev => ({ ...prev, [date]: !prev[date] }));
  };

  const handleDelete = () => {
    if (confirmDelete) {
      actions.deleteEntry(confirmDelete.date, confirmDelete.entryId);
      setConfirmDelete(null);
    }
  };

  const handleReset = () => {
    actions.resetToday();
    setConfirmReset(false);
  };

  const openEdit = (date, entry) => {
    setEditingEntry({ date, entryId: entry.id });
    setEditReps(String(entry.reps));
    setEditNotes(entry.notes || '');
    setEditActivityId(entry.activityId);
  };

  const handleSaveEdit = () => {
    if (!editingEntry) return;
    const activity = activities.find(a => a.id === editActivityId);
    if (!activity || !parseInt(editReps, 10)) return;
    const reps = parseInt(editReps, 10);
    actions.updateEntry(editingEntry.date, editingEntry.entryId, {
      activityId: activity.id,
      activityName: activity.name,
      activityColor: activity.color,
      reps,
      touchesPerRep: activity.touchesPerRep,
      notes: editNotes,
    });
    setEditingEntry(null);
  };

  const formatDate = (dateStr) => {
    const d = new Date(dateStr + 'T12:00:00');
    if (dateStr === todayKey) return 'Today';
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    if (dateStr === yesterday.toISOString().split('T')[0]) return 'Yesterday';
    return d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black text-white">History</h1>
          <p className="text-gray-500 text-sm">All your training entries</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setConfirmReset(true)}
            className="btn-danger flex items-center gap-1.5 text-xs"
          >
            <RotateCcw size={14} />
            Reset Today
          </button>
          <button
            onClick={() => exportToCSV(dailyLogs, activities)}
            className="btn-ghost flex items-center gap-1.5 text-xs"
          >
            <Download size={14} />
            Export CSV
          </button>
        </div>
      </div>

      {/* Touches over time chart */}
      {chartData.length > 1 && (
        <div className="glass-card p-4">
          <h2 className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-3">Total Touches Over Time</h2>
          <ResponsiveContainer width="100%" height={200}>
            <AreaChart data={chartData} margin={{ top: 5, right: 10, left: 0, bottom: 5 }}>
              <defs>
                <linearGradient id="touchGradient" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#818cf8" stopOpacity={0.3} />
                  <stop offset="100%" stopColor="#818cf8" stopOpacity={0} />
                </linearGradient>
              </defs>
              <XAxis dataKey="label" tick={{ fill: '#6b7280', fontSize: 11 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: '#6b7280', fontSize: 11 }} axisLine={false} tickLine={false} width={40} />
              <Tooltip
                contentStyle={{ background: '#1e1e2e', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', fontSize: '12px' }}
                labelStyle={{ color: '#9ca3af' }}
                itemStyle={{ color: '#818cf8' }}
              />
              <ReferenceLine y={goal} stroke="#4ade80" strokeDasharray="4 4" strokeOpacity={0.5} />
              <Area type="monotone" dataKey="touches" stroke="#818cf8" fill="url(#touchGradient)" strokeWidth={2} dot={{ r: 3, fill: '#818cf8' }} />
            </AreaChart>
          </ResponsiveContainer>
          <div className="flex items-center gap-4 mt-2 text-[10px] text-gray-500">
            <span className="flex items-center gap-1"><span className="w-3 h-0.5 bg-indigo-400 inline-block rounded" /> Touches</span>
            <span className="flex items-center gap-1"><span className="w-3 h-0.5 bg-emerald-400 inline-block rounded border-dashed" style={{ borderTop: '1px dashed #4ade80', height: 0 }} /> Daily Goal</span>
          </div>
        </div>
      )}

      {/* Search */}
      <div className="relative">
        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
        <input
          type="text"
          value={searchQuery}
          onChange={e => setSearchQuery(e.target.value)}
          placeholder="Search activities or notes..."
          className="input-field w-full pl-10"
        />
      </div>

      {/* Day groups */}
      <div className="space-y-3">
        {filteredDays.length === 0 ? (
          <div className="glass-card p-8 text-center text-gray-500">
            {searchQuery ? 'No entries match your search.' : 'No entries yet. Start logging!'}
          </div>
        ) : (
          filteredDays.map(day => (
            <div key={day.date} className="glass-card overflow-hidden">
              {/* Day header */}
              <button
                onClick={() => toggleDay(day.date)}
                className="w-full flex items-center justify-between p-4 hover:bg-white/[0.02] transition-colors"
              >
                <div className="flex items-center gap-3">
                  <span className="text-sm font-bold text-white">{formatDate(day.date)}</span>
                  <span className="text-xs text-gray-500">{day.date}</span>
                </div>
                <div className="flex items-center gap-4">
                  <div className="text-right">
                    <span className="text-sm font-bold text-brand-400">{day.total.toLocaleString()} touches</span>
                    <span className="text-xs text-gray-600 ml-2">{day.sessionCount} sessions</span>
                  </div>
                  {expandedDays[day.date] ? <ChevronUp size={16} className="text-gray-500" /> : <ChevronDown size={16} className="text-gray-500" />}
                </div>
              </button>

              {/* Entries */}
              <AnimatePresence>
                {expandedDays[day.date] && (
                  <motion.div
                    initial={{ height: 0 }}
                    animate={{ height: 'auto' }}
                    exit={{ height: 0 }}
                    className="overflow-hidden"
                  >
                    <div className="border-t border-white/5">
                      {day.entries.slice().reverse().map(entry => (
                        <div key={entry.id} className="flex items-center justify-between px-4 py-3 hover:bg-white/[0.02] border-b border-white/[0.02] last:border-0">
                          <div className="flex items-center gap-3">
                            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.activityColor || '#6366f1' }} />
                            <div>
                              <span className="text-sm font-semibold text-gray-200">{entry.activityName}</span>
                              {entry.notes && <span className="text-xs text-gray-600 ml-2">- {entry.notes}</span>}
                            </div>
                          </div>
                          <div className="flex items-center gap-4">
                            <div className="text-right">
                              <span className="text-xs text-gray-500">{entry.reps} reps &times; {entry.touchesPerRep}</span>
                              <span className="text-sm font-bold text-white ml-3">+{entry.totalTouches}</span>
                            </div>
                            <span className="text-xs text-gray-600 w-16 text-right">{entry.time}</span>
                            <button
                              onClick={() => openEdit(day.date, entry)}
                              className="p-1.5 rounded-lg hover:bg-brand-500/10 text-gray-600 hover:text-brand-400 transition-colors"
                            >
                              <Pencil size={14} />
                            </button>
                            <button
                              onClick={() => setConfirmDelete({ date: day.date, entryId: entry.id })}
                              className="p-1.5 rounded-lg hover:bg-red-500/10 text-gray-600 hover:text-red-400 transition-colors"
                            >
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ))
        )}
      </div>

      {/* Delete confirmation */}
      <Modal isOpen={!!confirmDelete} onClose={() => setConfirmDelete(null)} title="Delete Entry">
        <p className="text-gray-400 text-sm mb-4">Are you sure you want to delete this entry? This cannot be undone.</p>
        <div className="flex gap-3 justify-end">
          <button onClick={() => setConfirmDelete(null)} className="btn-ghost">Cancel</button>
          <button onClick={handleDelete} className="btn-danger">Delete</button>
        </div>
      </Modal>

      {/* Reset confirmation */}
      <Modal isOpen={confirmReset} onClose={() => setConfirmReset(false)} title="Reset Today's Progress">
        <p className="text-gray-400 text-sm mb-4">This will delete all of today's entries and reset your touch count to 0. Are you sure?</p>
        <div className="flex gap-3 justify-end">
          <button onClick={() => setConfirmReset(false)} className="btn-ghost">Cancel</button>
          <button onClick={handleReset} className="btn-danger">Reset Today</button>
        </div>
      </Modal>

      {/* Edit entry modal */}
      <Modal isOpen={!!editingEntry} onClose={() => setEditingEntry(null)} title="Edit Entry">
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2">Activity</label>
            <div className="grid grid-cols-2 gap-2">
              {activities.map(a => (
                <button
                  key={a.id}
                  type="button"
                  onClick={() => setEditActivityId(a.id)}
                  className={`p-2.5 rounded-xl border text-left transition-all ${
                    editActivityId === a.id
                      ? 'border-brand-500/50 bg-brand-600/10'
                      : 'border-white/5 bg-white/[0.02] hover:border-white/10'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full" style={{ backgroundColor: a.color }} />
                    <span className="text-xs font-semibold text-white truncate">{a.name}</span>
                  </div>
                  <span className="text-[10px] text-gray-500">{a.touchesPerRep} touch/rep</span>
                </button>
              ))}
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2">Reps</label>
            <input
              type="number"
              value={editReps}
              onChange={e => setEditReps(e.target.value)}
              className="input-field w-full text-lg font-bold text-center py-3"
              min="1"
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2">Notes</label>
            <input
              type="text"
              value={editNotes}
              onChange={e => setEditNotes(e.target.value)}
              placeholder="Optional notes..."
              className="input-field w-full"
            />
          </div>
          {editActivityId && parseInt(editReps, 10) > 0 && (
            <div className="bg-brand-600/10 border border-brand-500/20 rounded-xl p-3 text-center">
              <span className="text-xs text-gray-400">Total: </span>
              <span className="text-lg font-black text-brand-400">
                {parseInt(editReps, 10) * (activities.find(a => a.id === editActivityId)?.touchesPerRep || 0)}
              </span>
              <span className="text-xs text-gray-400"> touches</span>
            </div>
          )}
          <div className="flex gap-3 justify-end">
            <button onClick={() => setEditingEntry(null)} className="btn-ghost">Cancel</button>
            <button onClick={handleSaveEdit} className="btn-primary">Save Changes</button>
          </div>
        </div>
      </Modal>
    </div>
  );
}
